def remove_elements_at_indices(lst, indices):
    to_remove = set(i for i in indices if 0 <= i < len(lst))
    return [v for i, v in enumerate(lst) if i not in to_remove]

def insert_at_intervals(lst, item, interval):
    result = []
    n = len(lst)
    for i, v in enumerate(lst):
        result.append(v)
        if (i + 1) % interval == 0 and i != n - 1:
            result.append(item)
    return result

def max_sum_non_adjacent(lst):
    prev2, prev1 = 0, 0
    for x in lst:
        cur = max(prev1, prev2 + x)
        prev2, prev1 = prev1, cur
    return prev1

def last_index_of_maximum(lst):
    m = max(lst)
    for i in range(len(lst) - 1, -1, -1):
        if lst[i] == m:
            return i

def count_elements_greater_than_average(lst):
    avg = sum(lst) / len(lst)
    return sum(1 for x in lst if x > avg)

def remove_duplicates_preserve_order(lst):
    seen = set()
    result = []
    for x in lst:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def rotate_list_left(lst, n):
    if not lst:
        return []
    n = n % len(lst)
    return lst[n:] + lst[:n]

def rotate_list_right(lst, n):
    if not lst:
        return []
    n = n % len(lst)
    k = len(lst) - n
    return lst[k:] + lst[:k]

def find_duplicates(lst):
    counts = {}
    result = []
    for x in lst:
        counts[x] = counts.get(x, 0) + 1
        if counts[x] == 2:
            result.append(x)
    return result

def group_consecutive(lst):
    if not lst:
        return []
    result = []
    current = lst[0]
    count = 1
    for x in lst[1:]:
        if x == current:
            count += 1
        else:
            result.append([current, count])
            current = x
            count = 1
    result.append([current, count])
    return result

def second_largest(lst):
    distinct = set(lst)
    if len(distinct) < 2:
        return None
    return sorted(distinct)[-2]

def difference_preserve_order(a, b):
    b_set = set(b)
    seen = set()
    result = []
    for x in a:
        if x not in b_set and x not in seen:
            seen.add(x)
            result.append(x)
    return result

def partition_odd_even(lst):
    evens = [x for x in lst if x % 2 == 0]
    odds = [x for x in lst if x % 2 != 0]
    return (evens, odds)

def cumulative_max(lst):
    result = []
    if not lst:
        return result
    m = lst[0]
    for x in lst:
        m = max(m, x)
        result.append(m)
    return result

def count_occurrences(lst):
    result = {}
    for x in lst:
        result[x] = result.get(x, 0) + 1
    return result
